SQL="CREATE OR REPLACE FUNCTION public.m2_guard_task_snapshot()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE cstatus text; cversion uuid; tv uuid;\nBEGIN\n IF TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'M2 task snapshot may not be deleted' USING ERRCODE='23514';\n END IF;\n IF TG_OP='UPDATE' THEN\n   IF (NEW.case_id,NEW.template_task_id,NEW.key,NEW.kind,NEW.title,\n       NEW.description,NEW.owner_role,NEW.required,NEW.applicable,NEW.evidence_spec)\n      IS DISTINCT FROM\n      (OLD.case_id,OLD.template_task_id,OLD.key,OLD.kind,OLD.title,\n       OLD.description,OLD.owner_role,OLD.required,OLD.applicable,OLD.evidence_spec)\n   THEN RAISE EXCEPTION 'M2 task snapshot identity immutable' USING ERRCODE='23514';\n   END IF;\n   IF OLD.execution_state IN ('COMPLETED','CANCELLED')\n       AND NEW.execution_state IS DISTINCT FROM OLD.execution_state\n   THEN RAISE EXCEPTION 'M2 terminal task cannot reopen' USING ERRCODE='23514';\n   END IF;\n   RETURN NEW;\n END IF;\n SELECT status,template_version_id INTO cstatus,cversion\n   FROM public.onboarding_onboardingcase WHERE id=NEW.case_id FOR SHARE;\n SELECT version_id INTO tv FROM public.templates_templatetask\n   WHERE id=NEW.template_task_id FOR SHARE;\n IF cstatus IS DISTINCT FROM 'CREATED' OR tv IS DISTINCT FROM cversion THEN\n   RAISE EXCEPTION 'M2 task must instantiate on matching CREATED case' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_task_snapshot_guard BEFORE INSERT OR UPDATE OR DELETE\nON public.onboarding_task FOR EACH ROW EXECUTE FUNCTION public.m2_guard_task_snapshot();\n\nCREATE OR REPLACE FUNCTION public.m2_guard_task_edge_mutation()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE phase text;\nBEGIN\n IF TG_OP='UPDATE' OR TG_OP='DELETE' THEN\n   RAISE EXCEPTION 'M2 dependency topology immutable' USING ERRCODE='23514';\n END IF;\n SELECT status INTO phase FROM public.onboarding_onboardingcase\n   WHERE id=NEW.case_id FOR SHARE;\n IF phase IS DISTINCT FROM 'CREATED' THEN\n   RAISE EXCEPTION 'M2 cannot add dependency after activation' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m2_task_edge_immutable BEFORE INSERT OR UPDATE OR DELETE\nON public.onboarding_taskdependency FOR EACH ROW EXECUTE FUNCTION public.m2_guard_task_edge_mutation();\n\nCREATE OR REPLACE FUNCTION public.m2_guard_evidence_immutable()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n RAISE EXCEPTION 'M2 accepted evidence immutable' USING ERRCODE='23514';\nEND; $$;\nCREATE TRIGGER m2_attestation_immutable BEFORE UPDATE OR DELETE\nON public.onboarding_managerattestation FOR EACH ROW EXECUTE FUNCTION public.m2_guard_evidence_immutable();\nCREATE TRIGGER m2_completion_immutable BEFORE UPDATE OR DELETE\nON public.onboarding_taskcompletion FOR EACH ROW EXECUTE FUNCTION public.m2_guard_evidence_immutable();\n\nCREATE OR REPLACE FUNCTION public.m2_check_completed_manager_evidence()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nDECLARE state text; finished timestamptz; taskkind text; evidence_actor uuid;\nBEGIN\n SELECT execution_state,completed_at,kind INTO state,finished,taskkind\n FROM public.onboarding_task WHERE id=NEW.task_id;\n SELECT actor_id INTO evidence_actor\n FROM public.onboarding_managerattestation WHERE id=NEW.manager_attestation_id;\n IF state IS DISTINCT FROM 'COMPLETED' OR finished IS NULL\n   OR taskkind IS DISTINCT FROM 'MANAGER_PREPARATION'\n   OR evidence_actor IS DISTINCT FROM NEW.completed_by_id\n THEN RAISE EXCEPTION 'M2 completion lacks matching completed task evidence' USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE CONSTRAINT TRIGGER m2_completed_manager_evidence\nAFTER INSERT ON public.onboarding_taskcompletion\nDEFERRABLE INITIALLY DEFERRED\nFOR EACH ROW EXECUTE FUNCTION public.m2_check_completed_manager_evidence();"
REVERSE_SQL="DROP TRIGGER IF EXISTS m2_completed_manager_evidence ON public.onboarding_taskcompletion;\nDROP FUNCTION IF EXISTS public.m2_check_completed_manager_evidence();\nDROP TRIGGER IF EXISTS m2_completion_immutable ON public.onboarding_taskcompletion;\nDROP TRIGGER IF EXISTS m2_attestation_immutable ON public.onboarding_managerattestation;\nDROP FUNCTION IF EXISTS public.m2_guard_evidence_immutable();\nDROP TRIGGER IF EXISTS m2_task_edge_immutable ON public.onboarding_taskdependency;\nDROP FUNCTION IF EXISTS public.m2_guard_task_edge_mutation();\nDROP TRIGGER IF EXISTS m2_task_snapshot_guard ON public.onboarding_task;\nDROP FUNCTION IF EXISTS public.m2_guard_task_snapshot();"

